// #211: ProblemProvider/visualize answers for the Schedule picture type, captured from a local
// build of the full Redux backend (local/viz-integration, with the exact tank levels of Redux
// #887) on 2026-10-17, so tests/e2e/picture-renderers.spec.js can answer the picture requests
// itself and CI needs no backend that serves them. Kept apart from picture-payloads.js only for
// size (Biome checks files up to 1 MiB): each problem's default instance with its solver, a
// fractional Pump Scheduling instance, and the runs that end on no.
